    const a: WatchItem = { id: 1, title: 'A', watched: false };
    const b: WatchItem = { id: 2, title: 'B', watched: false };
    (store as any)._items.set([a, b]);
    store.toggleWatched(1);
    const ids = store.orderedItems().map(i => i.id);
    expect(ids).toEqual([2, 1]);
