import { describe, it, expect } from 'vitest';
import { TestBed } from '@angular/core/testing';
import { Watchlist } from '../app/watchlist/watchlist';
import { WatchlistStore } from '../app/watchlist-store';
import { WatchItem } from '../app/movie';

describe('Watchlist toggle behaviour', () => {
  function setup(items: WatchItem[]) {
    const store = new WatchlistStore();
    (store as any)._items.set([...items]);
    TestBed.configureTestingModule({});
    const fixture = TestBed.createComponent(Watchlist);
    fixture.componentInstance.store = store;
    fixture.detectChanges();
    return { fixture, store, el: fixture.nativeElement as HTMLElement };
  }

  it('toggles exactly the clicked movie by id, unwatched rendered first', () => {
    const a: WatchItem = { id: 10, title: 'Watched A', watched: true };
    const b: WatchItem = { id: 20, title: 'Unwatched B', watched: false };
    const { fixture, store, el } = setup([a, b]);
    // rendered order: b (unwatched) then a
    const checkboxes = el.querySelectorAll('input[type=checkbox]');
    expect(checkboxes.length).toBe(2);
    const idFor = (i: number) => store.orderedItems()[i].id;
    expect(idFor(0)).toBe(20);
    // click the checkbox of the second rendered row (id 10, watched=true)
    const target = checkboxes[1] as HTMLInputElement;
    target.click();
    fixture.detectChanges();
    expect(store.items().find(i => i.id === 10)?.watched).toBe(false);
    expect(store.items().find(i => i.id === 20)?.watched).toBe(false);
  });

  it('toggles once when blank row space is clicked', () => {
    const a: WatchItem = { id: 1, title: 'A', watched: false };
    const b: WatchItem = { id: 2, title: 'B', watched: true };
    const { fixture, store, el } = setup([a, b]);
    const rows = el.querySelectorAll('tr');
    expect(rows.length).toBeGreaterThan(1);
    const row = rows[0]; // first rendered row = id 1, unwatched
    (row as HTMLElement).click();
    fixture.detectChanges();
    expect(store.items().find(i => i.id === 1)?.watched).toBe(true);
    expect(store.items().find(i => i.id === 2)?.watched).toBe(true);
  });
});
